// 12 synthetische Leads über alle Phasen (BAUPLAN § 3.1.11) – keine echten Personen. Nur die Felder, die Tests brauchen; vollständige Zeilen per `vollerLead`.
import type { Lead, LeadStage } from '@/types/domain'

export const MEMBER_V = '00000000-0000-4000-8000-000000000001'
export const MEMBER_M = '00000000-0000-4000-8000-000000000002'

const STUFEN: LeadStage[] = [
  'neu',
  'vernetzung_gesendet',
  'vernetzt',
  'gespraech_eroeffnet',
  'dm_follow_up',
  'dm_beantwortet',
  'bedarfsermittlung',
  'pitch',
  'erstgespraech_vereinbart',
  'erstgespraech',
  'kunde',
  'langfristig',
]

export function vollerLead(i: number, patch: Partial<Lead> = {}): Lead {
  const n = String(i).padStart(2, '0')
  const basis = {
    id: `10000000-0000-4000-8000-0000000000${n}`,
    salutation: i % 3 === 0 ? 'frau' : i % 3 === 1 ? 'herr' : 'neutral',
    title: null,
    first_name: 'Test',
    last_name: `Person ${n}`,
    full_name: `Test Person ${n}`,
    role: i % 2 ? 'geschaeftsfuehrer' : 'kundenbetreuer',
    role_title: i % 2 ? 'Geschäftsführer' : 'Kundenbetreuer',
    company_id: null,
    company_name: `Solar ${n} GmbH`,
    city: 'Hamburg',
    website: null,
    linkedin_url: `https://www.linkedin.com/in/test-person-${n}/`,
    linkedin_url_norm: `linkedin.com/in/test-person-${n}`,
    sales_nav_url: null,
    url_verified: false,
    email: null,
    phone_e164: i % 4 === 0 ? '+4940123456' : null,
    phone_type: 'unbekannt',
    phone_source: 'unbekannt',
    phone_source_url: null,
    phone_collected_at: null,
    phone_numbers: [],
    owner_id: i % 2 ? MEMBER_V : MEMBER_M,
    sales_owner_id: null,
    opened_by_id: null,
    released: false,
    released_at: null,
    released_reason: null,
    stage: STUFEN[i % STUFEN.length] ?? 'neu',
    stage_changed_at: '2026-10-01T09:00:00+02:00',
    ended_reason: null,
    ended_at: null,
    ended_note: null,
    priority: 0,
    next_action_at: null,
    next_action_kind: null,
    next_action_ref: null,
    next_action_label: null,
    last_activity_at: null,
    last_activity_type: null,
    last_outbound_at: null,
    last_inbound_at: null,
    last_inbound_channel: null,
    inbound_unanswered_since: null,
    follow_up_count: 0,
    do_not_contact: false,
    do_not_contact_channels: null,
    objection_at: null,
    objection_note: null,
    email_consent_basis: 'none',
    email_consent_at: null,
    email_consent_note: null,
    email_consent_ref: null,
    call_basis: null,
    call_basis_note: null,
    call_basis_url: null,
    privacy_notice_sent_at: null,
    privacy_notice_version: null,
    qualification: null,
    notes: null,
    custom: null,
    source: 'app',
    source_batch_id: null,
    legacy_id: null,
    legacy_system_id: null,
    legacy_system_id_2: null,
    created_by: MEMBER_V,
    created_at: '2026-10-01T09:00:00+02:00',
    updated_at: '2026-10-01T09:00:00+02:00',
    deleted_at: null,
  }
  return { ...(basis as unknown as Lead), ...patch }
}

export const LEADS: Lead[] = Array.from({ length: 12 }, (_, i) => vollerLead(i + 1))
